#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float16,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DTypeKind {
    Bool,
    SignedInteger,
    UnsignedInteger,
    Integral,
    RealFloating,
    ComplexFloating,
    Numeric,
}

pub fn numpy_isdtype(dtype: NumpyDType, kind: DTypeKind) -> bool {
    use DTypeKind::*;
    use NumpyDType::*;

    match kind {
        Bool => dtype == Bool,

        SignedInteger => matches!(dtype, Int8 | Int16 | Int32 | Int64),

        UnsignedInteger => matches!(dtype, UInt8 | UInt16 | UInt32 | UInt64),

        Integral => matches!(
            dtype,
            Int8 | Int16 | Int32 | Int64 | UInt8 | UInt16 | UInt32 | UInt64
        ),

        RealFloating => matches!(dtype, Float16 | Float32 | Float64),

        ComplexFloating => matches!(dtype, Complex64 | Complex128),

        Numeric => matches!(
            dtype,
            Bool
                | Int8
                | Int16
                | Int32
                | Int64
                | UInt8
                | UInt16
                | UInt32
                | UInt64
                | Float16
                | Float32
                | Float64
                | Complex64
                | Complex128
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_numpy_isdtype() {
        assert!(numpy_isdtype(NumpyDType::Bool, DTypeKind::Bool));
        assert!(!numpy_isdtype(NumpyDType::Int32, DTypeKind::Bool));

        assert!(numpy_isdtype(NumpyDType::Int8, DTypeKind::SignedInteger));
        assert!(!numpy_isdtype(NumpyDType::UInt8, DTypeKind::SignedInteger));

        assert!(numpy_isdtype(NumpyDType::UInt64, DTypeKind::UnsignedInteger));
        assert!(!numpy_isdtype(NumpyDType::Int64, DTypeKind::UnsignedInteger));

        assert!(numpy_isdtype(NumpyDType::UInt32, DTypeKind::Integral));
        assert!(numpy_isdtype(NumpyDType::Int16, DTypeKind::Integral));

        assert!(numpy_isdtype(NumpyDType::Float32, DTypeKind::RealFloating));
        assert!(!numpy_isdtype(NumpyDType::Complex64, DTypeKind::RealFloating));

        assert!(numpy_isdtype(NumpyDType::Complex128, DTypeKind::ComplexFloating));
        assert!(!numpy_isdtype(NumpyDType::Float64, DTypeKind::ComplexFloating));

        assert!(numpy_isdtype(NumpyDType::Bool, DTypeKind::Numeric));
        assert!(numpy_isdtype(NumpyDType::Int32, DTypeKind::Numeric));
        assert!(numpy_isdtype(NumpyDType::Float64, DTypeKind::Numeric));
        assert!(numpy_isdtype(NumpyDType::Complex64, DTypeKind::Numeric));
    }
}